import{_ as e}from"./chunks/d0014_front_1920x800.0oTO6k7W.js";import{_ as t}from"./chunks/d0012_front_1920x800.Dwvn5mWx.js";import{_ as r,o,c as i,al as l}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"ModalAI Starling 2","description":"","frontmatter":{},"headers":[],"relativePath":"en/complete_vehicles_mc/modalai_starling.md","filePath":"en/complete_vehicles_mc/modalai_starling.md"}'),n={name:"en/complete_vehicles_mc/modalai_starling.md"};function s(d,a,m,p,c,h){return o(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="modalai-starling-2" tabindex="-1">ModalAI Starling 2 <a class="header-anchor" href="#modalai-starling-2" aria-label="Permalink to &quot;ModalAI Starling 2&quot;">​</a></h1><p>The <a href="https://www.modalai.com/pages/starlings" target="_blank" rel="noreferrer">Starlings</a> are NDAA-compliant SLAM development drones based on the <a href="./../flight_controller/modalai_voxl_2">VOXL 2</a> and PX4 with SWAP-optimized sensors and payloads optimized for indoor and outdoor autonomous navigation.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Starling drones house <em>VOXL 2</em>, which is a powerful companion computer, a PX4 flight controller, image sensors, GPS, and connectivity modem, in one small package. The Starlings feature ModalAI&#39;s open source <a href="https://gitlab.com/voxl-public/voxl-sdk" target="_blank" rel="noreferrer">VOXL SDK</a> that has pre-configured autonomy models for computer vision assisted flight.</p><p>These development drones are ready-to-fly out-of-the-box. They are designed to help you get to market faster and accelerate your application development and prototyping.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you are new to VOXL, be sure to familiarize yourself with the core features of VOXL hardware and software by reviewing the <a href="https://docs.modalai.com/voxl-developer-bootcamp/" target="_blank" rel="noreferrer">VOXL Bootcamp</a>.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For complete and regularly updated documentation, please visit <a href="https://docs.modalai.com/starling-2/" target="_blank" rel="noreferrer">https://docs.modalai.com/starling-2/</a> and <a href="https://docs.modalai.com/starling-2-max/" target="_blank" rel="noreferrer">https://docs.modalai.com/starling-2-max/</a>.</p></div><h2 id="starling-2" tabindex="-1">Starling 2 <a class="header-anchor" href="#starling-2" aria-label="Permalink to &quot;Starling 2&quot;">​</a></h2><p>The <a href="https://www.modalai.com/products/starling-2" target="_blank" rel="noreferrer">Starling 2</a> is an NDAA-compliant development drone supercharged by the VOXL SDK and equipped with a new image sensor suite for precise, indoor visual navigation and SLAM. Powered by the Blue UAS Framework autopilot, VOXL 2, the Starling 2 weighs 280g and boasts an impressive 40 minutes of autonomous flight time.</p><p><img src="'+e+'" alt="Image of the front of Starling 2"></p><h2 id="starling-2-max" tabindex="-1">Starling 2 Max <a class="header-anchor" href="#starling-2-max" aria-label="Permalink to &quot;Starling 2 Max&quot;">​</a></h2><p>The <a href="https://www.modalai.com/products/starling-2-max" target="_blank" rel="noreferrer">Starling 2 Max</a> is VOXL 2-powered, NDAA-compliant development drone supercharged by VOXL SDK specifically designed for computer vision-based, long-range dead reckoning with a 500g payload capacity. Powered by the Blue UAS Framework autopilot, VOXL 2, the Starling 2 Max weighs 500g and boasts an impressive 55 minutes of autonomous flight time.</p><p><img src="'+t+'" alt="Image of front of a Starling 2 Max"></p><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p><a href="https://www.modalai.com/products/starling-2" target="_blank" rel="noreferrer">ModalAI Starling 2</a></p><p><a href="https://www.modalai.com/products/starling-2-max" target="_blank" rel="noreferrer">ModalAI Starling 2 Max</a></p>',16)])])}const b=r(n,[["render",s]]);export{_ as __pageData,b as default};
